DOCUMENT();
############# # Load Macros #############
loadMacros( "PGstandard.pl", "PGML.pl", "AnswerFormatHelp.pl", "PGchoicemacros.pl", "contextForm.pl", "ORCCA.pl", "PGcourse.pl", ); COMMENT('Authored in PreTeXt');
####### # Setup #######
$var = list_random('a'..'n', 'p'..'z', 'A'..'D', 'F'..'N', 'P'..'T', 'V'..'Z'); Context("Numeric")->variables->are($var => 'Real'); ($a, $b) = (2..10)[NchooseK(9,2)]; $given = Formula("$a($var + $b)"); $ans = Formula("$a($b + $var)"); $evaluator = $ans->cmp(checker => sub{ my ($correct, $student, $ans) = @_; Value->Error("This is the original expression") if ($student eq $given); Value->Error("This is algebraically equivalent to the given expression, but using commutativity of multiplication would give you something else") if (($student == $correct) && ($student ne $correct)); return ($student eq $correct); });
############################# # Exercise Group Introduction #############################
BEGIN_PGML Demonstrate that you know the meanings of the various algebraic properties by applying the given algebraic property to the given expression to get a new expression.
END_PGML
###### # Body ######
BEGIN_PGML Apply commutativity of addition to [`[$given]\text{.}`]
[_]{$evaluator}{16}
END_PGML
